def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # The all-zero column separates the framed patterns from the colored shapes.
    split = next((c for c in range(1, w) if all(grid[r][c] == 0 for r in range(h))), w)
    left = [row[:split] for row in grid]
    lw = split

    # Record each colored shape as a cropped binary mask.
    shapes = {}
    for color in {v for row in grid for v in row if v not in (0, bg)}:
        cells = [(r, c) for r in range(h) for c in range(split, w)
                 if grid[r][c] == color]
        if cells:
            r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
            c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
            shapes[color] = (
                r1 - r0 + 1,
                c1 - c0 + 1,
                {(r - r0, c - c0) for r, c in cells}
            )

    # Horizontal full-background rows mark the boundaries of the framed panels.
    bounds = [r for r in range(h) if all(left[r][c] == bg for c in range(lw))]
    out = [row[:] for row in left]

    for top, bottom in zip(bounds, bounds[1:]):
        mask = {
            (r - top - 1, c - 1)
            for r in range(top + 1, bottom)
            for c in range(1, lw - 1)
            if left[r][c] == 0
        }
        ph, pw = bottom - top - 1, lw - 2
        for color, (sh, sw, shape_mask) in shapes.items():
            if (ph, pw) == (sh, sw) and mask == shape_mask:
                for r, c in mask:
                    out[top + 1 + r][1 + c] = color
                break

    return out
